import{z as s,x as c,o as r,c as B,q as i,j as n,D as e,d as E,s as o,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Teacher forcing","description":"","frontmatter":{"title":"Teacher forcing","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/teacher-forcing.md","filePath":"llm/teacher-forcing.md","lastUpdated":1791413859000}'),d={name:"llm/teacher-forcing.md"};function h(m,a,p,f,g,_){const l=c("Mermaid");return r(),B("div",null,[a[2]||(a[2]=i('<h1 id="teacher-forcing" tabindex="-1">Teacher forcing <a class="header-anchor" href="#teacher-forcing" aria-label="Permalink to &quot;Teacher forcing&quot;">​</a></h1><div class="epigraph"><p>训练时把金标准的前一个目标词喂给解码器，前向可以沿时间并行算损失；推理时却必须吃自己的预测，两条条件分布并不相同。</p><footer>—— 据 Williams &amp; Zipser, A Learning Algorithm for Continually Running Fully Recurrent Neural Networks, Neural Computation, 1989；Bengio et al., Scheduled Sampling, NeurIPS 2015 整理</footer></div><p><a href="/llm/seq2seq-encode-decode">Seq2Seq 编码解码</a>规定解码器每步读 \\(y_{t-1}\\)。本课不重画 \\(s\\)。缺口是：\\(y_{t-1}\\) 在训练与推理上来源不同。训练若用模型自己的抽样，错误会沿时间累积，早期难收敛；若用真值（teacher forcing），条件是对的，部署时却从未见过「自己刚写错一个词」的状态。本课把这份落差钉住。注意力下一课才出现，不在这里用对齐来掩盖强迫。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>解码器定义 \\(P(y_t\\mid y_{\\lt t},s)\\)。训练语料提供完整 \\(y_{1:m}\\)，于是可以在每一步把真值 \\(y_{t-1}\\) 当输入，同时用 \\(y_t\\) 当标签——与<a href="/llm/clm-as-next-token">下一词分类</a>相同，只是条件里多了 \\(s\\)。这样每步损失可并行（RNN 状态仍串行，但输入不再依赖模型输出）。缺口是：推理没有真值 \\(y_{\\lt t}\\)，必须用 \\(\\hat y_{\\lt t}\\)。若训练从未让解码器看见错误前缀，测试时一旦偏离，状态进入训练集外区域，错误级联。<span class="marginnote">teacher forcing 可以类比学车全程有教练扶方向盘：练习时每个动作都从正确位置出发，学得快；一上路没人扶，一个小偏差也得自己接着开——「没练过带着错误继续开」正是暴露偏差。</span></p><p>Williams &amp; Zipser 把「用真值当下一输入」称为 teacher forcing。它不是作弊标签——标签仍是 \\(y_t\\)，只是条件输入被替换。把 forcing 理解成「损失里用了未来」，是把输入与标签搞混。标签左移一位与 forcing 经常一起出现，但是两件事。<span class="marginnote">初学者容易把「标签左移一位」当成 forcing 本身。左移只是把 \\(y_t\\) 摆成标签的对齐技巧；forcing 指输入取真值还是取自身预测。两件事常一起出现，混为一谈会以为评估时也能喂真值。</span></p><h3 id="teacher-forcing-不是-scheduled-sampling-的同义词" tabindex="-1">Teacher forcing 不是 scheduled sampling 的同义词 <a class="header-anchor" href="#teacher-forcing-不是-scheduled-sampling-的同义词" aria-label="Permalink to &quot;Teacher forcing 不是 scheduled sampling 的同义词&quot;">​</a></h3><p>按一定概率把输入换成模型预测，是为了缩小训练—推理落差的后续补丁（Bengio et al., 2015）。本课的对象是默认协议：训练全强迫。未讲清楚强迫，采样调度没有对照。强迫也不会自动解决瓶颈 \\(s\\)：即使每步条件都是真值，解码器仍然只从 \\(s\\) 取源信息。落差与瓶颈是两个缺口。</p><p><span class="marginnote">强迫使训练时 \\(h_t^{\\mathrm{dec}}\\) 走在「金标准前缀」的轨迹上。推理轨迹不同，即使参数相同。评估必须走推理协议：自回归展开，不能用真值输入报 BLEU。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练步：编码器读源得到 \\(s\\)；解码器输入序列是 \\(\\langle\\mathrm{bos}\\rangle,y_1,\\ldots,y_{m-1}\\)，标签是 \\(y_1,\\ldots,y_m\\)；损失为掩码平均交叉熵。推理：从 \\(\\langle\\mathrm{bos}\\rangle\\) 与 \\(s\\) 开始，每步取 \\(\\hat y_t\\)，写回下一步输入，直到 EOS 或最大长度。束搜索改变的是取 \\(\\hat y\\) 的方式，不改变「输入是自身输出」。暴露偏差（exposure bias）即两条轨迹的差异。<span class="marginnote">「暴露偏差」翻译成大白话：训练时模型被暴露在完美前缀下，推理时却暴露在自己可能出错的输出下——不是能力变了，是见过的世界不一样。</span></p>',11)),(r(),n(A,null,{default:e(()=>[o(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOLD%5B%22%E7%9C%9F%E5%80%BC%E5%89%8D%E7%BC%80%22%5D%20--%3E%20TR%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9Ateacher%20forcing%22%5D%0A%20%20TR%20--%3E%20LOSS%5B%22%E5%90%84%E6%AD%A5%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20PRED%5B%22%E8%87%AA%E8%BA%AB%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20INF%5B%22%E6%8E%A8%E7%90%86%EF%BC%9A%E8%87%AA%E5%9B%9E%E5%BD%92%22%5D%0A%20%20INF%20--%3E%20DRIFT%5B%22%E7%8A%B6%E6%80%81%E5%81%8F%E7%A6%BB%E8%AE%AD%E7%BB%83%E8%BD%A8%E8%BF%B9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"强迫把信用分配变局部：当前交叉熵主要责怪当前步的分类头，因为输入是对的。好处是信号稳定、收敛快。坏处是模型从未练习「带着错误继续写」。长目标上级联更明显。缓解可以是计划采样、自己生成再训练（SEARN 一类）、或后课注意力让每步直接读源从而减少对自身前缀的脆弱依赖——但注意力并不取消这条协议差异。",-1)),(r(),n(A,null,{default:e(()=>[o(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E7%AC%AC2%E6%AD%A5%E5%86%99%E9%94%99%E4%B8%80%E4%B8%AA%E8%AF%8D%22%5D%20--%3E%20TF%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9A%E4%B8%8B%E4%B8%80%E6%AD%A5%E8%BE%93%E5%85%A5%E4%BB%8D%E6%98%AF%E7%9C%9F%E5%80%BC%20y2%22%5D%0A%20%20TF%20--%3E%20OK%5B%22%E9%94%99%E8%AF%AF%E4%B8%8D%E4%BC%A0%E6%92%AD%EF%BC%9A%E5%8F%AA%E6%9C%89%E7%AC%AC2%E6%AD%A5%E7%9A%84%E6%8D%9F%E5%A4%B1%E5%8D%87%E9%AB%98%22%5D%0A%20%20E%20--%3E%20INF%5B%22%E6%8E%A8%E7%90%86%EF%BC%9A%E7%AC%AC3%E6%AD%A5%E8%BE%93%E5%85%A5%E6%98%AF%E9%94%99%E8%AF%AF%E7%9A%84%20%C5%B72%22%5D%0A%20%20INF%20--%3E%20CASC%5B%22%E7%8A%B6%E6%80%81%E8%BF%9B%E5%85%A5%E8%AE%AD%E7%BB%83%E9%9B%86%E5%A4%96%E5%8C%BA%E5%9F%9F%EF%BC%9A%E9%94%99%E8%AF%AF%E7%BA%A7%E8%81%94%22%5D%0A%20%20CASC%20--%3E%20FIX%5B%22%E7%BC%93%E8%A7%A3%EF%BC%9A%E8%AE%A1%E5%88%92%E9%87%87%E6%A0%B7%20%2F%20%E8%87%AA%E7%94%9F%E6%88%90%E5%86%8D%E8%AE%AD%E7%BB%83%20%2F%20%E6%AF%8F%E6%AD%A5%E8%AF%BB%E6%BA%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">这张图回答的问题是：同一个小错误，两种协议下为何命运不同。forcing 把每一步的错误「就地结算」，自回归则把错误写进下一步的输入——一个词的偏差可能滚成整段跑偏，这就是暴露偏差想要暴露的那条裂缝。</span></p><p>与语言模型预训练的关系：纯 LM 训练也是 forcing（真值前缀）。聊天推理同样自回归。Seq2Seq 只是把同一落差放在「还有一个源」的条件下，显得更刺眼。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入加性注意力。下一课<a href="/llm/bahdanau-additive-attention">Bahdanau 加性注意力</a>针对瓶颈 \\(s\\)，让解码器每步读全体编码器隐状态。后课默认：训练用 teacher forcing 除非声明；报告生成质量必须走自回归协议。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Teacher forcing 用真值 \\(y_{t-1}\\) 当解码器输入，标签仍是 \\(y_t\\)。</li><li>推理吃自身预测，轨迹与训练不同，错误会级联。</li><li>强迫不等于泄漏未来标签；评估不能在真值输入下报生成指标。</li><li>计划采样是后续补丁，不是本课默认。</li><li>出处：Williams &amp; Zipser, 1989；Bengio et al., NeurIPS 2015。</li></ul>',6))])}const F=s(d,[["render",h]]);export{D as __pageData,F as default};
